"    // 4. Fetch Tables
    try {
      const tableRes = await posService.getTables();
      const serverTables = tableRes.data || [];
      setTables(prev => {
        const localTempTables = prev.filter(t => t.is_temporary);
        return [...serverTables, ...localTempTables];
      });
      localStorage.setItem('pos_tables_cache', JSON.stringify(serverTables));
    } catch (e) {
      console.warn("initApp - Failed to load tables:", e);
    }

    // Fetch Table Departments
    try {
      const outletId = business?.user_id || business?.parent_user_id || business?.id;
      const deptRes = await posService.getTableDepartments(outletId);
      const serverDepts = deptRes.data || [];
      setTableDepartments(serverDepts);
      localStorage.setItem('pos_table_departments', JSON.stringify(serverDepts));
    } catch (e) {
      console.warn("initApp - Failed to load table departments:", e);
      try {
        const cachedDepts = localStorage.getItem('pos_table_departments');
        if (cachedDepts) setTableDepartments(JSON.parse(cachedDepts));
      } catch (err) {
        console.error("Failed to parse cached table departments:", err);
      }
    }"

